  const profileView=`<section class="grid-2"><div class="card page-panel"><div class="section-head"><div><h2>My Profile</h2><p class="page-sub">Details prefilled by your gym.</p></div><button id="profileEdit2" class="mini-btn primary">Edit</button></div><div class="profile-summary">${photo}<div><h3>${esc(m.name)}</h3><p>${esc(m.phone)} · ${esc(m.gender||'')}</p><span class="tag success">${esc(m.status)}</span></div></div><div class="detail-list"><div><span>Plan</span><b>${esc(m.plan)}</b></div><div><span>Expiry</span><b>${fmtDate(m.expiry)}</b></div><div><span>Member Access Code</span><b>${m.code}</b></div><div><span>Gym</span><b>${esc(g.name||'Gym')}</b></div></div></div><div class="card page-panel"><div class="section-head"><div><h3>Digital ID Card</h3><span>Keep your access code private</span></div></div><div class="id-card">${'<div class="id-brand">'+esc(g.name||'GymFlow')+'</div><div class="id-name">'+esc(m.name)+'</div><div class="id-meta"><span>'+esc(m.plan)+'</span><span>'+fmtDate(m.expiry)+'</span></div><div class="id-code"><div>Access Code</div><strong>'+m.code+'</strong></div>'}</div></div></section>`;
  let body=home;if(memberSection==='attendance')body=attendanceView;else if(memberSection==='fitness')body=fitnessView;else if(memberSection==='workouts')body=workoutView;else if(memberSection==='diet')body=dietView;else if(memberSection==='profile')body=profileView;
  app.innerHTML=`<div class="app-shell"><div class="dashboard-shell"><aside class="sidebar"><div class="side-brand"><div class="mini-brand-icon">${navIcon('dumbbell')}</div><div><div class="brand-kicker">Member</div><div class="brand-name">${esc(g.name||'GymFlow')}</div></div></div><div class="nav"><button class="nav-item ${memberSection==='home'?'active':''}" data-ms="home">${navIcon('grid')}<span>Overview</span></button><button class="nav-item ${memberSection==='attendance'?'active':''}" data-ms="attendance">${navIcon('qr')}<span>Attendance</span></button><button class="nav-item ${memberSection==='fitness'?'active':''}" data-ms="fitness">${navIcon('card')}<span>Health & Performance</span></button><button class="nav-item ${memberSection==='workouts'?'active':''}" data-ms="workouts">${navIcon('dumbbell')}<span>Workouts</span></button><button class="nav-item ${memberSection==='diet'?'active':''}" data-ms="diet">${navIcon('file')}<span>Diet</span></button><button class="nav-item ${memberSection==='profile'?'active':''}" data-ms="profile">${navIcon('users')}<span>My Profile</span></button></div><div class="side-bottom"><div class="help-card"><strong>Access Code</strong><span>${m.code}<br>Keep this code private.</span></div><button id="memberLogout" class="nav-item">${navIcon('logout')}<span>Log out</span></button></div></aside><main class="main"><header class="topbar"><div class="top-actions"><button id="memberMobileMenu" class="icon-btn mobile-menu">${navIcon('grid')}</button><div class="greeting"><h1>Welcome, ${esc(m.name.split(' ')[0])}</h1><p>${esc(m.plan)} · ${d<0?'Expired':d+' days remaining'}</p></div></div><div class="top-actions"><button id="memberScanTop" class="icon-btn">${navIcon('qr')}</button><div class="avatar">${initials(m.name)}</div></div></header><div class="content">${body}</div></main></div><div class="bottom-nav" id="memberBottomNav"></div></div><div id="overlay" class="overlay"></div><div class="toast"></div>`;
  document.querySelectorAll('[data-ms]').forEach(b=>b.onclick=()=>{memberSection=b.dataset.ms;renderMember()});
  document.getElementById('memberLogout').onclick=()=>{logout()};
  document.getElementById('memberMobileMenu').onclick=()=>{modal(`<h3>Member Dashboard</h3><div class="list">${['home','attendance','fitness','workouts','diet','profile'].map(x=>`<button class="list-item mini-btn" data-ms2="${x}">${x==='home'?'Overview':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div>`);document.querySelectorAll('[data-ms2]').forEach(b=>b.onclick=()=>{memberSection=b.dataset.ms2;closeModal();renderMember()})};
  document.getElementById('memberScanTop').onclick=openMemberScanner;
  ['checkInBtn','scanAttendance'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=openMemberScanner});
  ['editProfileBtn','healthEdit','fitnessEdit','profileEdit2'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=openMemberProfileEdit});
  ['viewWorkouts'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=()=>{memberSection='workouts';renderMember()}});['viewDiets'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=()=>{memberSection='diet';renderMember()}});
  document.querySelectorAll('[data-workout-done]').forEach(b=>b.onclick=()=>{const ms=members();const mm=ms.find(x=>x.id===m.id);mm.workoutsDone=(mm.workoutsDone||0)+1;write('members',ms);toast('Workout session added to your progress.');renderMember()});
  const bottom=document.getElementById('memberBottomNav');if(bottom){const keys=[['home','grid','Home'],['attendance','qr','QR'],['fitness','card','Health'],['profile','users','Profile']];bottom.innerHTML=keys.map(([id,ic,l])=>`<button class="${memberSection===id?'active':''}" data-ms="${id}">${navIcon(ic)}<br>${l}</button>`).join('');bottom.querySelectorAll('[data-ms]').forEach(b=>b.onclick=()=>{memberSection=b.dataset.ms;renderMember()})}
