(async()=>{try{await loadData();startLiveSync()}catch(e){console.error(e);booting=false;app.innerHTML='<div class="auth-wrap"><div class="auth-card"><div class="auth-left"><h1 class="hero-title">GymFlow is starting…</h1><p class="hero-sub">Please refresh once the secure database connection is ready.</p><div class="error">'+esc(e.message||'Connection error')+'</div></div></div></div>'}})();


/* =============================================================
   GymFlow V2 functionality layer
   - UPI Intent checkout (plan amount is enforced server-side)
   - Payment requests / owner confirmation
   - PWA install + browser/service-worker notifications
   - Refined Soft Neumorphism Light Blue UI
   - WhatsApp API intentionally not included
   ============================================================= */
KEY.orders='gf_orders';
KEY.notifications='gf_notifications';
KEY.push='gf_push_enabled';

// Extend the existing record mapper without changing the original schema.
function recordType(k){
  return ({gyms:'gyms',members:'members',plans:'plans',payments:'payments',invoices:'invoices',attendance:'attendance',workouts:'workouts',diets:'diets',orders:'orders',notifications:'notifications'})[k];
}

function upiPayload({upiId,name,amount,txnRef,note}={}){
  const parts=new URLSearchParams();
  parts.set('pa',String(upiId||''));
  parts.set('pn',String(name||'GymFlow Gym'));
  parts.set('am',Number(amount||0).toFixed(2));
  parts.set('cu','INR');
  if(txnRef) parts.set('tr',txnRef);
  if(note) parts.set('tn',note);
  return `upi://pay?${parts.toString()}`;
}
function validUpiId(v){return /^[a-zA-Z0-9._-]{2,}@[a-zA-Z0-9.-]{2,}$/i.test(String(v||'').trim())}
function activeGym(){const u=active();return u?gyms()[u.gymId]||{}:{} }
function qrMarkup(text){
  try{if(window.qrcode){const qr=window.qrcode(0,'M');qr.addData(text);qr.make();return qr.createSvgTag({cellSize:5,margin:2,scalable:true});}}catch(e){}
  return qrSvg(text);
}
function copyText(text,label='Copied'){
  const done=()=>toast(label);
  if(navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(done).catch(()=>fallbackCopy(text,done)); else fallbackCopy(text,done);
}
function fallbackCopy(text,done){const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');done()}finally{ta.remove()}}
function showWebNotification(title,body,tag='gymflow'){
  if(!('Notification' in window)||Notification.permission!=='granted')return;
  navigator.serviceWorker?.ready?.then(r=>r.showNotification(title,{body,icon:'./icon.svg',badge:'./icon.svg',tag,renotify:false})).catch(()=>{try{new Notification(title,{body,icon:'./icon.svg',tag})}catch(e){}});
}
function requestNotifications(){
  if(!('Notification' in window)){toast('This browser does not support notifications.');return}
  Notification.requestPermission().then(p=>{if(p==='granted'){localStorage.setItem(KEY.push,'1');toast('Notifications enabled.');runSmartNotifications(true)}else toast('Notifications are still off. You can enable them from browser settings.')});
}
function notificationItems(){
  const {m}=ownerData(); const items=[]; const now=today();
  for(const x of m){
    const d=daysLeft(x.expiry);
    if(x.status==='Blocked') items.push({id:`blocked-${x.id}`,title:`${x.name} is blocked`,body:'Review the member status before accepting access.',type:'member'});
    else if(d<0) items.push({id:`expired-${x.id}`,title:`Membership expired: ${x.name}`,body:`Expired on ${fmtDate(x.expiry)}.`,type:'expiry'});
    else if(d<=3) items.push({id:`expiry-${x.id}`,title:`Membership expires in ${Math.max(0,d)} day${d===1?'':'s'}: ${x.name}`,body:'Open Members to renew this membership.',type:'expiry'});
    else if(x.status==='Due') items.push({id:`due-${x.id}`,title:`Payment due: ${x.name}`,body:`Plan: ${x.plan}. Review payment status.`,type:'payment'});
  }
  const pending=orders().filter(x=>x.status==='Pending');
  for(const o of pending.slice(0,8)) items.push({id:o.id,title:`UPI payment request: ${o.memberName}`,body:`₹${Number(o.amount||0).toLocaleString('en-IN')} · ${o.planName||'Membership plan'} is waiting for confirmation.`,type:'payment'});
  const unique=new Map();items.forEach(i=>unique.set(i.id,i));return [...unique.values()].slice(0,20);
}
function runSmartNotifications(force=false){
  const u=active();if(!u||u.role!=='owner')return;
  const items=notificationItems();
  const prev=JSON.parse(localStorage.getItem(KEY.notifications)||'[]');
  const seen=new Set(prev.map(x=>x.id));
  const next=[...items.map(x=>({...x,createdAt:x.createdAt||new Date().toISOString(),read:false})),...prev].slice(0,40);
  localStorage.setItem(KEY.notifications,JSON.stringify(next));
  if(force && localStorage.getItem(KEY.push)==='1' && items[0] && !seen.has(items[0].id)) showWebNotification(items[0].title,items[0].body,items[0].id);
}
function installPwa(){
  if(!window.__gfInstallPrompt){toast('Install prompt is not available yet. Use your browser menu → Add to Home Screen.');return}
  window.__gfInstallPrompt.prompt();window.__gfInstallPrompt.userChoice.then(({outcome})=>{window.__gfInstallPrompt=null;if(outcome==='accepted')toast('GymFlow installed as an app.');else toast('Install cancelled.')});
}
function registerPwa(){
  if(!('serviceWorker' in navigator))return;
  navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(e=>console.warn('GymFlow SW registration failed',e));
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.__gfInstallPrompt=e;renderInstallBanner();});
  window.addEventListener('appinstalled',()=>{window.__gfInstallPrompt=null;document.querySelector('.install-banner')?.remove();toast('GymFlow installed successfully.');});
}
function renderInstallBanner(){
  if(!window.__gfInstallPrompt || document.querySelector('.install-banner'))return;
  const host=document.createElement('div');host.className='install-banner';
  host.innerHTML=`<div style="flex:1"><strong>Install GymFlow</strong><span>Get the full-screen app experience and faster access.</span></div><button class="btn btn-primary btn-small" id="installNow">Install App</button><button class="btn btn-secondary btn-small" id="installClose" style="width:42px;padding:0">×</button>`;
  document.body.appendChild(host);installNow.onclick=installPwa;installClose.onclick=()=>host.remove();
}
registerPwa();

function navIcon(name){const p={grid:'<path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',qr:'<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><path d="M14 14h3v3h3v3h-6v-6z"/>',card:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',dumbbell:'<path d="M6 4v16M18 4v16M3 8v8M21 8v8M6 12h12M3 10h3v4H3zM18 10h3v4h-3z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.6 1.6 0 0 0 .32 1.76l.05.05-1.84 1.84-.05-.05a1.6 1.6 0 0 0-1.76-.32 1.6 1.6 0 0 0-.97 1.47V20h-2.6v-.25a1.6 1.6 0 0 0-.97-1.47 1.6 1.6 0 0 0-1.76.32l-.05.05-1.84-1.84.05-.05A1.6 1.6 0 0 0 8.3 15a1.6 1.6 0 0 0-1.47-.97H6.6v-2.6h.23A1.6 1.6 0 0 0 8.3 10a1.6 1.6 0 0 0-.32-1.76l1.84-1.84.05.05A1.6 1.6 0 0 0 11.6 6.7a1.6 1.6 0 0 0 .97-1.47V5h2.6v.25A1.6 1.6 0 0 0 16.13 6.7a1.6 1.6 0 0 0 1.76-.32l.05-.05 1.84 1.84-.05.05A1.6 1.6 0 0 0 19.4 10c.3.58.89.97 1.55.97h.45v2.6h-.45c-.66 0-1.25.39-1.55.97z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',download:'<path d="M12 3v11m0 0 4-4m-4 4-4-4M5 21h14"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3M21 19a2 2 0 0 1 2 2v-2M12 3h7a2 2 0 0 1 2 2v3"/>',check:'<path d="m5 12 4 4L19 6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${p[name]||p.grid}</svg>`}

function orders(){return read('orders',[])}
function notifications(){return read('notifications',[])}

// Owner database loader extended with order/notification records.
async function loadData(){
  const s=await supabase.auth.getSession();const session=s.data.session;
  if(!session){booting=false;render();return}
  const {data:p,error:pe}=await supabase.from('gymflow_profiles').select('*').eq('id',session.user.id).maybeSingle();
  if(pe)throw pe;if(!p){await supabase.auth.signOut();booting=false;render();return}
  const {data:rows,error:re}=await supabase.from('gymflow_records').select('*').eq('gym_id',p.gym_id);
  if(re)throw re;
  const next={accounts:[],gyms:{},members:[],plans:[],payments:[],invoices:[],attendance:[],workouts:[],diets:[],orders:[],notifications:[],active:{id:session.user.id,role:p.role,memberId:p.member_id,gymId:p.gym_id,gymName:'',name:p.name||'Owner',mobile:session.user.phone?.replace(/^\+91/,'')||''}};
  for(const r of rows||[]){if(r.record_type==='gyms')next.gyms[r.payload.id]=r.payload;else if(next[r.record_type])next[r.record_type].push(r.payload)}
  next.active.gymName=next.gyms[p.gym_id]?.name||'GymFlow';store=next;setActive(next.active);booting=false;render();runSmartNotifications();renderInstallBanner();
}

// Keep notification/order collections in the same tenant-scoped persistence path.
async function persistCollection(k,v){
  const type=recordType(k);if(!type||!active())return;const gymId=active().gymId;
  if(type==='gyms'){const g=v[gymId];if(!g)return;const {error}=await supabase.from('gymflow_records').upsert({id:g.id||gymId,gym_id:gymId,record_type:'gyms',payload:g});if(error)throw error;return}
  const rows=Array.isArray(v)?v.filter(x=>x.gymId===gymId):[];
  const {data:old,error:readErr}=await supabase.from('gymflow_records').select('id').eq('gym_id',gymId).eq('record_type',type);if(readErr)throw readErr;
  const wanted=new Set(rows.map(x=>x.id));const remove=(old||[]).map(x=>x.id).filter(id=>!wanted.has(id));
  if(remove.length){const {error}=await supabase.from('gymflow_records').delete().in('id',remove);if(error)throw error}
  if(rows.length){const {error}=await supabase.from('gymflow_records').upsert(rows.map(x=>({id:x.id,gym_id:gymId,record_type:type,payload:x})));if(error)throw error}
}

function ownerNav(){const items=[['overview','grid','Overview'],['members','users','Members'],['attendance','qr','Attendance'],['payments','card','Payments'],['invoices','file','Invoices'],['plans','card','Plans'],['workouts','dumbbell','Workouts & Diet'],['settings','settings','Settings']];return items.map(([id,ic,l])=>`<button class="nav-item ${activeSection===id?'active':''}" data-nav="${id}">${navIcon(ic)}<span>${l}</span></button>`).join('')}

function openNotificationCenter(){
  runSmartNotifications();
  const items=notificationItems();
  modal(`<h3>Notifications</h3><p>Payment requests, membership expiry and member attention alerts from your gym.</p><div class="notify-list">${items.length?items.map(x=>`<div class="notify-item"><i class="notify-dot"></i><div><strong>${esc(x.title)}</strong><small>${esc(x.body)}</small></div><button class="mini-btn" data-notify-go="${esc(x.type)}">Open</button></div>`).join(''):'<div class="empty">Everything is clear right now.</div>'}</div><div class="modal-actions" style="margin-top:14px"><button id="enableNotifications" class="btn btn-primary btn-small">Enable App Notifications</button><button id="installFromNotify" class="btn btn-secondary btn-small">Install App</button><button class="btn btn-secondary btn-small" data-close>Done</button></div>`);
  document.querySelectorAll('[data-notify-go]').forEach(b=>b.onclick=()=>{closeModal();const t=b.dataset.notifyGo;activeSection=t==='payment'?'payments':t==='expiry'||t==='member'?'members':activeSection;render()});
  enableNotifications.onclick=requestNotifications;installFromNotify.onclick=installPwa;
}

