// Member checkout helpers.
async function memberBuyPlan(plan){
  const u=active(),m=currentMember(),g=gyms()[u.gymId]||{};
  if(!m||!plan)return;if(m.status==='Blocked'||daysLeft(m.expiry)<0){toast('Membership is inactive or expired. Contact your gym.');return}
  if(!validUpiId(g.upi)){modal(`<h3>Online payment is not configured</h3><p>Your gym has not added its UPI ID yet. Ask the gym owner to finish Payment Setup.</p><button class="btn btn-secondary btn-small" data-close>Done</button>`);return}
  const order={id:uid('ORD'),planId:plan.id,amount:Number(plan.price),date:today(),txnRef:`GF-${Date.now().toString(36).toUpperCase()}`,status:'Pending'};
  try{const {data,error}=await supabase.rpc('gymflow_member_create_order',{p_code:u.memberCode,p_order:order});if(error)throw error;store.orders=[...(store.orders||[]),data||order];const link=upiPayload({upiId:g.upi,name:g.upiName||g.name,amount:plan.price,txnRef:data?.txnRef||order.txnRef,note:g.upiNote||`${plan.name} membership`});
    modal(`<h3>Continue to UPI</h3><p>${esc(plan.name)} · exact amount <strong>₹${Number(plan.price).toLocaleString('en-IN')}</strong>.</p><div class="upi-preview"><div class="upi-qr">${qrMarkup(link)}</div><div><div class="page-sub">Your order is saved as <strong>${esc(data?.id||order.id)}</strong>. Confirm payment in your UPI app, then the gym owner will verify the payment.</div><div class="upi-link-box" style="margin-top:10px">${esc(link)}</div><div class="modal-actions" style="margin-top:12px"><button id="openMemberUpi" class="btn btn-primary btn-small">Open UPI App →</button><button id="copyMemberUpi" class="btn btn-secondary btn-small">Copy Link</button><button class="btn btn-secondary btn-small" data-close>Later</button></div></div></div>`);openMemberUpi.onclick=()=>window.location.href=link;copyMemberUpi.onclick=()=>copyText(link,'UPI payment link copied');toast('Payment request created.');
  }catch(e){toast(e.message||'Could not start payment.')}
}
function renderMemberPlans(){
  const u=active(),m=currentMember(),g=gyms()[u.gymId]||{},p=plans().filter(x=>x.gymId===m.gymId),pending=orders().filter(x=>x.memberId===m.id&&x.status==='Pending');
  return `<section class="card page-panel"><div class="section-head"><div><h2>Membership Plans</h2><p class="page-sub">Choose your gym plan and pay the exact amount through your UPI app.</p></div><span>${validUpiId(g.upi)?'UPI enabled':'Payment unavailable'}</span></div>${validUpiId(g.upi)?'':'<div class="hint" style="margin-bottom:14px">Online checkout will appear here after your gym owner adds a UPI ID.</div>'}<div class="cards-grid member-plans-grid">${p.length?p.map((x,i)=>`<article class="card member-card member-plan-card"><span class="featured-chip">${i===0?'Popular':'Plan'}</span><div class="member-name">${esc(x.name)}</div><div class="plan-price" style="margin-top:14px">₹${Number(x.price).toLocaleString('en-IN')}</div><div class="page-sub" style="margin-top:8px">${x.duration} days</div><p class="page-sub">${esc(x.description||'Gym access')}</p><div class="member-actions"><button class="mini-btn primary" ${!validUpiId(g.upi)?'disabled':''} data-buy-plan="${x.id}">Buy Plan →</button></div></article>`).join(''):'<div class="empty">Your gym has not published any membership plans yet.</div>'}</div><div class="section-head" style="margin-top:22px"><div><h3>My online payment requests</h3><span>Pending requests stay visible until the gym confirms the payment.</span></div></div><div class="list">${pending.length?pending.map(o=>`<div class="order-row"><div class="order-main"><strong>${esc(o.planName||'Membership')}</strong><small>${esc(o.id)} · ${fmtDate(o.date||today())}</small></div><div class="order-amount">₹${Number(o.amount).toLocaleString('en-IN')}</div><span class="tag warning">Pending</span></div>`).join(''):'<div class="empty">No pending payment requests.</div>'}</div></section>`;
}

function renderMember(){
  const u=active(),m=members().find(x=>x.id===u?.memberId),g=gyms()[u?.gymId]||{};if(!m){sessionStorage.removeItem(KEY.active);setActive(null);render();return}
  const {logs,streak}=memberMarkMetrics(m);const d=daysLeft(m.expiry);const ws=workouts().filter(x=>x.gymId===m.gymId);const ds=diets().filter(x=>x.gymId===m.gymId);const checked=logs.some(x=>x.date===today());
  const photo=m.photo?`<img src="${esc(m.photo)}" alt="${esc(m.name)}" class="profile-photo">`:`<div class="profile-photo placeholder">${initials(m.name)}</div>`;
  const home=`<section class="hero-panel"><div><div class="eyebrow">Member Experience</div><h2>Train smarter. Stay consistent.</h2><p>${checked?'You are checked in for today. Keep the momentum going.':'You have not checked in yet. Start today with one tap.'}</p><div class="quick-actions"><button id="checkInBtn" class="btn btn-primary btn-small">${checked?'Checked In ✓':'Scan & Check In'}</button><button id="memberPlansCta" class="btn btn-secondary btn-small">View Membership Plans</button></div></div><div class="hero-graphic"><div class="hero-ring"></div><div class="hero-glyph">${initials(m.name)}</div><div style="position:absolute;right:18px;top:18px;padding:8px 12px;border-radius:999px;background:#f6fbff;box-shadow:var(--shadow-soft);font-size:11px;font-weight:800;color:#2275c5">${d<0?'Expired':d+' days left'}</div></div></section><section class="metrics"><div class="card metric"><div class="metric-label">Check-ins</div><div class="metric-value">${logs.length}</div><div class="metric-sub">Attendance records</div></div><div class="card metric"><div class="metric-label">Day Streak</div><div class="metric-value">${streak}</div><div class="metric-sub">Keep the streak alive</div></div><div class="card metric"><div class="metric-label">Days Left</div><div class="metric-value">${Math.max(0,d)}</div><div class="metric-sub">${esc(m.plan)}</div></div><div class="card metric"><div class="metric-label">BMI</div><div class="metric-value">${m.height&&m.weight?(Number(m.weight)/(Number(m.height)/100)**2).toFixed(1):'—'}</div><div class="metric-sub">Health snapshot</div></div></section><section class="grid-2"><div class="card section-card"><div class="section-head"><h3>My Profile</h3><button id="editProfileBtn" class="mini-btn">Edit</button></div><div class="profile-summary">${photo}<div><h3>${esc(m.name)}</h3><p>${esc(m.phone)} · ${esc(m.gender||'')}</p><span class="tag success">${esc(m.status||'Active')}</span></div></div><div class="detail-list"><div><span>Goal</span><b>${esc(m.goal||'General Fitness')}</b></div><div><span>Plan</span><b>${esc(m.plan)}</b></div><div><span>Expiry</span><b>${fmtDate(m.expiry)}</b></div></div></div><div class="card section-card"><div class="section-head"><h3>Quick Progress</h3><span>Today</span></div><div class="performance-grid"><div class="perf"><b>${Number(m.steps||0).toLocaleString('en-IN')}</b><span>Steps</span></div><div class="perf"><b>${m.water||0} L</b><span>Water</span></div><div class="perf"><b>${m.workoutsDone||0}</b><span>Workouts</span></div><div class="perf"><b>${streak}</b><span>Streak</span></div></div></div></section>`;
  const attendanceView=`<section class="grid-2"><div class="card page-panel"><div class="section-head"><div><h2>Attendance</h2><p class="page-sub">Use your live camera or upload a photo of today’s gym QR.</p></div><span>${logs.length} total</span></div><div class="scanner-cta"><div><strong>${checked?'You are checked in today':'Ready to check in?'}</strong><small>Today’s QR is valid only for your gym and today’s India date.</small></div><button id="scanAttendance" class="btn btn-primary btn-small">${checked?'Scan Again':'Open Scanner'}</button></div><div class="stat-band"><div class="stat-tile"><span>Today</span><b>${checked?'Present':'Not checked in'}</b></div><div class="stat-tile"><span>Streak</span><b>${streak} days</b></div><div class="stat-tile"><span>Goal</span><b>${esc(m.goal||'Fitness')}</b></div></div></div><div class="card page-panel"><div class="section-head"><div><h3>Attendance History</h3><span>Recent check-ins</span></div></div><div class="list">${logs.slice(0,15).reverse().map(x=>`<div class="list-item"><div><strong>${fmtDate(x.date)}</strong><small>${esc(x.time||'')} · ${esc(x.source||'scanner')}</small></div><span class="tag success">Present</span></div>`).join('')||'<div class="empty">No attendance records yet.</div>'}</div></div></section>`;
  const fitnessView=`<section class="grid-2"><div class="card page-panel"><div class="section-head"><div><h2>Health Tracker</h2><p class="page-sub">Keep your latest body metrics here.</p></div><button id="fitnessEdit" class="mini-btn">Update</button></div><div class="health-grid"><div class="health-tile"><span>Current Weight</span><b>${m.weight?m.weight+' kg':'Add'}</b></div><div class="health-tile"><span>Height</span><b>${m.height?m.height+' cm':'Add'}</b></div><div class="health-tile"><span>Waist</span><b>${m.waist?m.waist+' cm':'Add'}</b></div><div class="health-tile"><span>Chest</span><b>${m.chest?m.chest+' cm':'Add'}</b></div></div></div><div class="card page-panel"><div class="section-head"><div><h2>Performance</h2><p class="page-sub">Your activity snapshot.</p></div></div><div class="performance-grid"><div class="perf"><b>${Number(m.steps||0).toLocaleString('en-IN')}</b><span>Steps today</span></div><div class="perf"><b>${m.water||0} L</b><span>Water</span></div><div class="perf"><b>${m.workoutsDone||0}</b><span>Workouts</span></div><div class="perf"><b>${streak}</b><span>Day streak</span></div></div></div></section>`;
  const workoutView=`<section class="card page-panel"><div class="section-head"><div><h2>Workouts & Training</h2><p class="page-sub">Programs created by your gym.</p></div></div><div class="cards-grid">${ws.map(x=>`<article class="card member-card"><div class="member-top"><div><div class="member-name">${esc(x.name)}</div><small>${esc(x.detail)}</small></div><div class="member-avatar">${x.exercises}</div></div><div class="member-details"><div class="detail"><span>Schedule</span><b>${esc(x.days)}</b></div><div class="detail"><span>Exercises</span><b>${x.exercises}</b></div></div><div class="member-actions"><button class="mini-btn primary" data-workout-done="${x.id}">Mark Completed</button></div></article>`).join('')||'<div class="empty">No workout templates yet.</div>'}</div></section>`;
  const dietView=`<section class="card page-panel"><div class="section-head"><div><h2>Diet & Nutrition</h2><p class="page-sub">Nutrition templates shared by your gym.</p></div></div><div class="cards-grid">${ds.map(x=>`<article class="card member-card"><div class="member-name">${esc(x.name)}</div><p class="page-sub">${esc(x.detail)}</p><div class="detail"><span>Focus</span><b>Balanced nutrition</b></div></article>`).join('')||'<div class="empty">No diet templates yet.</div>'}</div></section>`;
  const profileView=`<section class="grid-2"><div class="card page-panel"><div class="section-head"><div><h2>My Profile</h2><p class="page-sub">Details prefilled by your gym.</p></div><button id="profileEdit2" class="mini-btn primary">Edit</button></div><div class="profile-summary">${photo}<div><h3>${esc(m.name)}</h3><p>${esc(m.phone)} · ${esc(m.gender||'')}</p><span class="tag success">${esc(m.status)}</span></div></div><div class="detail-list"><div><span>Plan</span><b>${esc(m.plan)}</b></div><div><span>Expiry</span><b>${fmtDate(m.expiry)}</b></div><div><span>Member Access Code</span><b>${m.code}</b></div><div><span>Gym</span><b>${esc(g.name||'Gym')}</b></div></div></div><div class="card page-panel"><div class="section-head"><div><h3>Digital ID Card</h3><span>Keep your access code private</span></div></div><div class="id-card"><div class="id-brand">${esc(g.name||'GymFlow')}</div><div class="id-name">${esc(m.name)}</div><div class="id-meta"><span>${esc(m.plan)}</span><span>${fmtDate(m.expiry)}</span></div><div class="id-code"><div>Access Code</div><strong>${m.code}</strong></div></div></div></section>`;
  let body=home;if(memberSection==='attendance')body=attendanceView;else if(memberSection==='fitness')body=fitnessView;else if(memberSection==='workouts')body=workoutView;else if(memberSection==='diet')body=dietView;else if(memberSection==='profile')body=profileView;else if(memberSection==='plans')body=renderMemberPlans();
  app.innerHTML=`<div class="app-shell"><div class="dashboard-shell"><aside class="sidebar"><div class="side-brand"><div class="mini-brand-icon">${navIcon('dumbbell')}</div><div><div class="brand-kicker">Member</div><div class="brand-name">${esc(g.name||'GymFlow')}</div></div></div><div class="nav"><button class="nav-item ${memberSection==='home'?'active':''}" data-ms="home">${navIcon('grid')}<span>Overview</span></button><button class="nav-item ${memberSection==='plans'?'active':''}" data-ms="plans">${navIcon('card')}<span>Plans</span></button><button class="nav-item ${memberSection==='attendance'?'active':''}" data-ms="attendance">${navIcon('qr')}<span>Attendance</span></button><button class="nav-item ${memberSection==='fitness'?'active':''}" data-ms="fitness">${navIcon('card')}<span>Health & Performance</span></button><button class="nav-item ${memberSection==='workouts'?'active':''}" data-ms="workouts">${navIcon('dumbbell')}<span>Workouts</span></button><button class="nav-item ${memberSection==='diet'?'active':''}" data-ms="diet">${navIcon('file')}<span>Diet</span></button><button class="nav-item ${memberSection==='profile'?'active':''}" data-ms="profile">${navIcon('users')}<span>My Profile</span></button></div><div class="side-bottom"><div class="help-card"><strong>Access Code</strong><span>${m.code}<br>Keep this code private.</span></div><button id="memberLogout" class="nav-item">${navIcon('logout')}<span>Log out</span></button></div></aside><main class="main"><header class="topbar"><div class="top-actions"><button id="memberMobileMenu" class="icon-btn mobile-menu">${navIcon('grid')}</button><div class="greeting"><h1>Welcome, ${esc(m.name.split(' ')[0])}</h1><p>${esc(m.plan)} · ${d<0?'Expired':d+' days remaining'}</p></div></div><div class="top-actions"><button id="memberNotify" class="icon-btn" title="Notifications">${navIcon('settings')}</button><button id="memberScanTop" class="icon-btn" title="Attendance">${navIcon('qr')}</button><div class="avatar">${initials(m.name)}</div></div></header><div class="content">${body}</div></main></div><div class="bottom-nav" id="memberBottomNav"></div></div><div id="overlay" class="overlay"></div><div class="toast"></div>`;
  document.querySelectorAll('[data-ms]').forEach(b=>b.onclick=()=>{memberSection=b.dataset.ms;renderMember()});
  memberLogout.onclick=logout;memberScanTop.onclick=openMemberScanner;memberNotify.onclick=()=>requestNotifications();memberMobileMenu.onclick=()=>{modal(`<h3>Member Dashboard</h3><p>Select a section.</p><div class="list">${[['home','Overview'],['plans','Plans'],['attendance','Attendance'],['fitness','Health'],['workouts','Workouts'],['diet','Diet'],['profile','Profile']].map(([id,l])=>`<button class="list-item mini-btn" data-ms2="${id}">${l}</button>`).join('')}</div>`);document.querySelectorAll('[data-ms2]').forEach(b=>b.onclick=()=>{memberSection=b.dataset.ms2;closeModal();renderMember()})};
  ['checkInBtn','scanAttendance'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=openMemberScanner});['editProfileBtn','healthEdit','fitnessEdit','profileEdit2'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=openMemberProfileEdit});
  if(document.getElementById('memberPlansCta'))memberPlansCta.onclick=()=>{memberSection='plans';renderMember()};
  document.querySelectorAll('[data-buy-plan]').forEach(b=>b.onclick=()=>memberBuyPlan(plans().find(x=>x.id===b.dataset.buyPlan)));
  document.querySelectorAll('[data-workout-done]').forEach(b=>b.onclick=()=>{const ms=members();const mm=ms.find(x=>x.id===m.id);mm.workoutsDone=(mm.workoutsDone||0)+1;write('members',ms);toast('Workout session added to your progress.');renderMember()});
  const bottom=document.getElementById('memberBottomNav');if(bottom){const keys=[['home','grid','Home'],['plans','card','Plans'],['attendance','qr','QR'],['fitness','card','Health'],['profile','users','Profile']];bottom.innerHTML=keys.map(([id,ic,l])=>`<button class="${memberSection===id?'active':''}" data-ms="${id}">${navIcon(ic)}<br>${l}</button>`).join('');bottom.querySelectorAll('[data-ms]').forEach(b=>b.onclick=()=>{memberSection=b.dataset.ms;renderMember()})}
  renderInstallBanner();
}

