/* =============================================================
   GymFlow V3 production notification + AI-assist layer
   - Real Web Push subscription / VAPID handshake
   - Daily server-scheduled connection notifications (handled by Edge Function)
   - Member notification center + read state
   - Owner notification center + broadcast console
   - Smart/AI-assisted daily owner tasks from live gym data
   - PWA install / push UX and deep links
   - WhatsApp intentionally excluded
   ============================================================= */

KEY.orders='gf_orders';
KEY.notifications='gf_notifications';
KEY.push='gf_push_enabled';

let pushSyncPromise=null;
let memberNotificationCache={items:[],at:0};
let ownerNotificationCache={items:[],at:0};
let ownerTaskCache={items:[],at:0};

function recordType(k){return ({gyms:'gyms',members:'members',plans:'plans',payments:'payments',invoices:'invoices',attendance:'attendance',workouts:'workouts',diets:'diets',orders:'orders'})[k]}
function orders(){return read('orders',[])}
function notifications(){return read('notifications',[])}
function activeGym(){const u=active();return u?gyms()[u.gymId]||{}:{}}
function upiPayload({upiId,name,amount,txnRef,note}={}){const parts=new URLSearchParams();parts.set('pa',String(upiId||''));parts.set('pn',String(name||'GymFlow Gym'));parts.set('am',Number(amount||0).toFixed(2));parts.set('cu','INR');if(txnRef)parts.set('tr',txnRef);if(note)parts.set('tn',note);return `upi://pay?${parts.toString()}`}
function validUpiId(v){return /^[a-zA-Z0-9._-]{2,}@[a-zA-Z0-9.-]{2,}$/i.test(String(v||'').trim())}
function qrMarkup(text){try{if(window.qrcode){const qr=window.qrcode(0,'M');qr.addData(text);qr.make();return qr.createSvgTag({cellSize:5,margin:2,scalable:true});}}catch(e){}return qrSvg(text)}
function copyText(text,label='Copied'){const done=()=>toast(label);if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(done).catch(()=>fallbackCopy(text,done));else fallbackCopy(text,done)}
function fallbackCopy(text,done){const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');done()}finally{ta.remove()}}

function b64UrlToUint8Array(base64String){const padding='='.repeat((4-base64String.length%4)%4);const base64=(base64String+padding).replace(/-/g,'+').replace(/_/g,'/');const raw=atob(base64);return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
async function getPushRegistration(){if(!('serviceWorker' in navigator)||!('PushManager' in window))throw new Error('Push notifications are not supported by this browser.');return navigator.serviceWorker.ready}
async function getVapidPublicKey(){const r=await callFunction('gymflow-notifications',{action:'public-key'});if(!r?.publicKey)throw new Error('Push notification service is not configured yet.');return r.publicKey}
async function syncPushSubscription(){
  if(pushSyncPromise)return pushSyncPromise;
  pushSyncPromise=(async()=>{
    const u=active();
    if(!u)return false;
    if(!('Notification' in window)||Notification.permission!=='granted')return false;
    const reg=await getPushRegistration();
    let sub=await reg.pushManager.getSubscription();
    if(!sub){const publicKey=await getVapidPublicKey();sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64UrlToUint8Array(publicKey)});}
    const payload={action:'register',role:u.role,memberCode:u.role==='member'?u.memberCode:undefined,subscription:sub.toJSON(),userAgent:navigator.userAgent};
    const r=await callFunction('gymflow-notifications',payload);
    if(!r?.ok)throw new Error(r?.error||'Could not register notifications.');
    localStorage.setItem(KEY.push,'1');
    return true;
  })().catch(e=>{console.warn('GymFlow push sync:',e.message);return false}).finally(()=>{pushSyncPromise=null});
  return pushSyncPromise;
}
async function requestNotifications(){
  if(!('Notification' in window)){toast('This browser does not support push notifications.');return}
  if(!('serviceWorker' in navigator)||!('PushManager' in window)){toast('Push notifications are not available here. Install/open GymFlow in a supported browser.');return}
  try{
    const permission=await Notification.requestPermission();
    if(permission!=='granted'){toast(permission==='denied'?'Notifications are blocked. Enable them in browser settings.':'Notifications are still off.');return}
    const ok=await syncPushSubscription();
    if(!ok){toast('Could not connect this device to GymFlow notifications.');return}
    try{await callFunction('gymflow-notifications',{action:'test',role:active()?.role,memberCode:active()?.role==='member'?active().memberCode:undefined});toast('Notifications connected successfully 🔔')}catch(e){toast('Notifications enabled. Test delivery will retry automatically.')}
    if(active()?.role==='member')await refreshMemberNotifications(true);else await refreshOwnerNotifications(true);
    render();
  }catch(e){toast(e.message||'Could not enable notifications.')}
}
async function unregisterPushSubscription(){
  const u=active();if(!u||!('serviceWorker' in navigator))return;
  try{const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription();if(!sub)return;await callFunction('gymflow-notifications',{action:'unregister',role:u.role,memberCode:u.role==='member'?u.memberCode:undefined,endpoint:sub.endpoint});}catch(e){console.warn('GymFlow unregister push:',e.message)}
}
async function refreshMemberNotifications(force=false){
  const u=active();if(!u||u.role!=='member')return [];
  if(!force&&Date.now()-memberNotificationCache.at<25000)return memberNotificationCache.items;
  try{const {data,error}=await supabase.rpc('gymflow_member_notifications',{p_code:u.memberCode});if(error)throw error;memberNotificationCache={items:Array.isArray(data)?data:[],at:Date.now()};return memberNotificationCache.items}catch(e){console.warn('member notifications:',e.message);return memberNotificationCache.items}
}
async function refreshOwnerNotifications(force=false){
  const u=active();if(!u||u.role!=='owner')return [];
  if(!force&&Date.now()-ownerNotificationCache.at<25000)return ownerNotificationCache.items;
  try{const {data,error}=await supabase.from('gymflow_notifications').select('id,gym_id,audience,kind,title,body,url,priority,scheduled_for,published_at,data,created_at').eq('gym_id',u.gymId).order('created_at',{ascending:false}).limit(50);if(error)throw error;ownerNotificationCache={items:data||[],at:Date.now()};return ownerNotificationCache.items}catch(e){console.warn('owner notifications:',e.message);return ownerNotificationCache.items}
}
function unreadMemberCount(items){return (items||[]).filter(x=>!x.read).length}
function unreadOwnerCount(items){return (items||[]).filter(x=>x.audience==='owner' && x.kind!=='broadcast' || x.audience==='all_members').length}
async function markMemberNotificationRead(id){const u=active();if(!u||u.role!=='member')return;try{await supabase.rpc('gymflow_member_mark_notification',{p_code:u.memberCode,p_notification_id:id})}catch(e){console.warn(e)}memberNotificationCache={items:memberNotificationCache.items.map(n=>n.id===id?{...n,read:true}:n),at:Date.now()}}
function installPwa(){if(window.__gfInstallPrompt){window.__gfInstallPrompt.prompt();window.__gfInstallPrompt.userChoice.then(({outcome})=>{window.__gfInstallPrompt=null;if(outcome==='accepted')toast('GymFlow installed as an app.');else toast('Install cancelled.')});return}toast('Use your browser menu → Add to Home Screen to install GymFlow.')}
function registerPwa(){
  if(!('serviceWorker' in navigator))return;
  navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(e=>console.warn('GymFlow SW registration failed',e));
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.__gfInstallPrompt=e;renderInstallBanner()});
  window.addEventListener('appinstalled',()=>{window.__gfInstallPrompt=null;document.querySelector('.install-banner')?.remove();toast('GymFlow installed successfully.')});
  navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='OPEN_NOTIFICATION'){const url=e.data?.notification?.url;if(url){try{history.replaceState({},'',url)}catch(_){}location.reload()}}});
}
function renderInstallBanner(){if(!window.__gfInstallPrompt||document.querySelector('.install-banner'))return;const host=document.createElement('div');host.className='install-banner';host.innerHTML=`<div style="flex:1"><strong>Install GymFlow</strong><span>Full-screen app, faster access and reliable notifications.</span></div><button class="btn btn-primary btn-small" id="installNow">Install App</button><button class="btn btn-secondary btn-small" id="installClose" style="width:42px;padding:0">×</button>`;document.body.appendChild(host);document.getElementById('installNow').onclick=installPwa;document.getElementById('installClose').onclick=()=>host.remove()}
registerPwa();

function applyDeepLink(){const section=new URLSearchParams(location.search).get('section');if(!section)return;if(active()?.role==='owner'&&['overview','members','attendance','payments','invoices','plans','workouts','broadcasts','tasks','settings'].includes(section))activeSection=section;if(active()?.role==='member'&&['home','attendance','fitness','workouts','diet','profile','plans','notifications'].includes(section))memberSection=section==='notifications'?'home':section}

function ownerNav(){const items=[['overview','grid','Overview'],['members','users','Members'],['attendance','qr','Attendance'],['payments','card','Payments'],['invoices','file','Invoices'],['plans','card','Plans'],['workouts','dumbbell','Workouts & Diet'],['tasks','check','AI Tasks'],['broadcasts','bell','Broadcast'],['settings','settings','Settings']];return items.map(([id,ic,l])=>`<button class="nav-item ${activeSection===id?'active':''}" data-nav="${id}">${navIcon(ic)}<span>${l}</span></button>`).join('')}
function renderSection(){if(activeSection==='overview')renderOverview();else if(activeSection==='members')renderMembers();else if(activeSection==='attendance')renderAttendance();else if(activeSection==='payments')renderPayments();else if(activeSection==='invoices')renderInvoices();else if(activeSection==='plans')renderPlans();else if(activeSection==='workouts')renderWorkouts();else if(activeSection==='broadcasts')renderBroadcasts();else if(activeSection==='tasks')renderOwnerTasks();else if(activeSection==='settings')renderSettings();}

function notificationItems(){return ownerNotificationCache.items||[]}
async function openNotificationCenter(){
  if(active()?.role==='member'){
    const items=await refreshMemberNotifications(true);
    modal(`<div class="notify-modal-head"><div><div class="eyebrow">Your GymFlow</div><h3>Notifications</h3><p>Small reminders, useful updates and messages from your gym. 💙</p></div><span class="notif-count">${unreadMemberCount(items)} unread</span></div><div class="notify-list">${items.length?items.slice(0,30).map(n=>`<article class="notify-item ${n.read?'read':'unread'}"><i class="notify-dot ${n.kind||''}"></i><div><strong>${esc(n.title)}</strong><small>${esc(n.body)}</small><time>${new Date(n.createdAt||Date.now()).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div>${!n.read?`<button class="mini-btn" data-mark-notify="${n.id}">Read</button>`:''}</article>`).join(''):'<div class="empty">No messages yet. Your next check-in will appear here. ✨</div>'}</div><div class="modal-actions" style="margin-top:15px"><button id="enableMemberPush" class="btn btn-primary btn-small">${(typeof Notification!=='undefined'?Notification.permission:'default')==='granted'?'Reconnect Notifications':'Enable Notifications 🔔'}</button><button id="installMemberFromNotify" class="btn btn-secondary btn-small">Install App</button><button class="btn btn-secondary btn-small" data-close>Done</button></div>`);
    document.querySelectorAll('[data-mark-notify]').forEach(b=>b.onclick=async()=>{await markMemberNotificationRead(b.dataset.markNotify);await openNotificationCenter()});
    document.getElementById('enableMemberPush').onclick=requestNotifications;document.getElementById('installMemberFromNotify').onclick=installPwa;
    return;
  }
  const items=await refreshOwnerNotifications(true);
  modal(`<div class="notify-modal-head"><div><div class="eyebrow">Owner Command Center</div><h3>Notifications</h3><p>Payments, renewals, tasks and gym updates in one place.</p></div><span class="notif-count">${items.length} recent</span></div><div class="notify-list">${items.length?items.slice(0,30).map(n=>`<article class="notify-item"><i class="notify-dot"></i><div><strong>${esc(n.title)}</strong><small>${esc(n.body)}</small><time>${new Date(n.created_at||Date.now()).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div></article>`).join(''):'<div class="empty">Everything is clear for now. 🌿</div>'}</div><div class="modal-actions" style="margin-top:15px"><button id="ownerNotifEnable" class="btn btn-primary btn-small">${(typeof Notification!=='undefined'?Notification.permission:'default')==='granted'?'Reconnect Notifications':'Enable Notifications 🔔'}</button><button id="ownerNotifTasks" class="btn btn-secondary btn-small">Open AI Tasks</button><button id="ownerNotifBroadcast" class="btn btn-secondary btn-small">Broadcast</button><button id="ownerNotifInstall" class="btn btn-secondary btn-small">Install App</button><button class="btn btn-secondary btn-small" data-close>Done</button></div>`);
  ownerNotifEnable.onclick=requestNotifications;ownerNotifTasks.onclick=()=>{closeModal();activeSection='tasks';render()};ownerNotifBroadcast.onclick=()=>{closeModal();activeSection='broadcasts';render()};ownerNotifInstall.onclick=installPwa;
}

