  const notices=notificationItems();
  app.innerHTML=`<div class="app-shell"><div class="dashboard-shell"><aside class="sidebar"><div class="side-brand"><div class="mini-brand-icon">${navIcon('dumbbell')}</div><div><div class="brand-kicker">Gym Management</div><div class="brand-name">${esc(g.name||'GymFlow')}</div></div></div><nav class="nav">${ownerNav()}</nav><div class="side-bottom"><div class="help-card"><strong>${esc(g.name||u.gymName||'My Gym')}</strong><span>${esc(g.city||'—')}<br>${esc(g.phone||u.mobile||'')}</span></div><button id="logoutBtn" class="nav-item">${navIcon('logout')}<span>Log out</span></button></div></aside><main class="main"><header class="topbar"><div class="top-actions"><button id="mobileMenu" class="icon-btn mobile-menu">${navIcon('grid')}</button><div class="greeting"><h1>${greeting()}, ${esc(u.name||'Owner')}</h1><p>${esc(g.name||'Your gym')} · ${notices.length?notices.length+' smart alerts':'Everything looks calm'}</p></div></div><div class="top-actions"><input id="globalSearch" class="search" placeholder="Search members, invoices..."/><button id="notifyBtn" class="icon-btn notif-button" title="Notifications">${navIcon('bell')}<span class="notif-badge">${Math.min(99,notices.filter(n=>n.audience==='owner'||n.audience==='all_members').length)}</span></button><button id="installTop" class="icon-btn" title="Install App">${navIcon('download')}</button><div class="avatar">${initials(u.name||'GO')}</div></div></header><div id="pageContent" class="content"></div></main></div><div class="bottom-nav" id="bottomNav"></div></div><div id="overlay" class="overlay"></div><div class="toast"></div>`;
