function renderTaskCards(tasks){const body=document.getElementById('tasksBody');if(!body)return;body.innerHTML=tasks.length?`<div class="smart-task-list">${tasks.map((t,i)=>`<article class="smart-task ${t.completed?'done':''}"><div class="task-rank">${i+1}</div><div class="task-main"><div class="task-top"><span class="task-category">${esc(String(t.category||'Operations').replace('_',' '))}</span><span class="task-priority">${t.priority>=90?'High':'Normal'}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.detail)}</p><div class="task-actions"><button class="mini-btn primary" data-task-open="${esc(t.action_section||'overview')}">${esc(t.action||'Open')}</button><button class="mini-btn ${t.completed?'primary':''}" data-task-done="${t.id}">${t.completed?'✓ Completed':'Mark Done'}</button></div></div></article>`).join('')}</div>`:'<div class="empty">No actions are needed right now. Enjoy the calm. 🌿</div>';document.querySelectorAll('[data-task-open]').forEach(b=>b.onclick=()=>{const target=b.dataset.taskOpen;closeModal();activeSection=target;render()});document.querySelectorAll('[data-task-done]').forEach(b=>b.onclick=async()=>{try{const id=b.dataset.taskDone;const done=ownerTaskCache.items.find(t=>t.id===id);const {error}=await supabase.from('gymflow_owner_tasks').update({completed:true,completed_at:new Date().toISOString()}).eq('id',id).eq('owner_user_id',active().id);if(error)throw error;if(done)done.completed=true;renderTaskCards(ownerTaskCache.items);toast('Task completed. Nice work. 💙')}catch(e){toast(e.message||'Could not complete task.')}})}

function renderBroadcasts(){
  const host=document.getElementById('pageContent');if(!host)return;
  host.innerHTML=`<section class="grid-2"><section class="card page-panel broadcast-compose"><div class="section-head"><div><div class="eyebrow">Member Connection</div><h2>Broadcast a message</h2><p class="page-sub">Send one warm, useful update to your gym's active members.</p></div><span class="plan-check">Push enabled</span></div><form id="broadcastForm" class="form-grid"><div class="field"><label>Title</label><input id="bcTitle" class="input" maxlength="70" placeholder="Sunday workout tomorrow" required></div><div class="field"><label>Message</label><textarea id="bcBody" class="textarea" maxlength="280" placeholder="Short, genuine and useful. Keep it human. 💙" required></textarea><div class="char-count" id="bcCount">0 / 280</div></div><div class="field-row"><div class="field"><label>Emoji</label><select id="bcEmoji" class="select"><option>📣</option><option>💪</option><option>🔥</option><option>❤️</option><option>🎯</option><option>🏆</option><option>🌟</option><option>😊</option></select></div><div class="field"><label>Priority</label><select id="bcPriority" class="select"><option value="normal">Normal</option><option value="high">High</option></select></div></div><div class="broadcast-preview"><span>Preview</span><strong id="bcPreviewTitle">📣 Your message title</strong><small id="bcPreviewBody">Your message will appear here.</small></div><div id="bcError" class="error"></div><div class="modal-actions"><button id="sendBroadcastBtn" class="btn btn-primary">Send to active members →</button><button type="button" id="broadcastEnablePush" class="btn btn-secondary">Enable owner notifications</button></div></form></section><section class="card page-panel"><div class="section-head"><div><h3>Recent broadcasts</h3><span>Latest messages sent from this gym</span></div></div><div id="broadcastHistory" class="notify-list"><div class="empty">Loading history…</div></div></section></section>`;
  bcBody.oninput=()=>{bcCount.textContent=`${bcBody.value.length} / 280`;bcPreviewBody.textContent=bcBody.value||'Your message will appear here.';bcPreviewTitle.textContent=`${bcEmoji.value} ${bcTitle.value||'Your message title'}`};bcTitle.oninput=bcBody.oninput;bcEmoji.onchange=bcBody.oninput;broadcastEnablePush.onclick=requestNotifications;
  broadcastForm.onsubmit=async e=>{e.preventDefault();bcError.textContent='';const title=bcTitle.value.trim(),message=bcBody.value.trim();if(title.length<2||message.length<2){bcError.textContent='Add a title and message.';return}sendBroadcastBtn.disabled=true;sendBroadcastBtn.textContent='Sending…';try{const r=await callFunction('gymflow-notifications',{action:'broadcast',title,message,emoji:bcEmoji.value,priority:bcPriority.value,url:'./?section=home'});toast(`Broadcast sent to ${r?.recipients||0} active notification device${r?.recipients===1?'':'s'}. 📣`);broadcastForm.reset();bcBody.oninput();await loadBroadcastHistory()}catch(ex){bcError.textContent=ex.message||'Could not send broadcast.'}finally{sendBroadcastBtn.disabled=false;sendBroadcastBtn.textContent='Send to active members →'}};
  loadBroadcastHistory();
}
async function loadBroadcastHistory(){const host=document.getElementById('broadcastHistory');if(!host||!active())return;try{const {data,error}=await supabase.from('gymflow_notifications').select('id,title,body,created_at,published_at,kind,audience').eq('gym_id',active().gymId).eq('kind','broadcast').eq('audience','all_members').order('created_at',{ascending:false}).limit(20);if(error)throw error;host.innerHTML=data?.length?data.map(n=>`<article class="notify-item"><i class="notify-dot broadcast"></i><div><strong>${esc(n.title)}</strong><small>${esc(n.body)}</small><time>${new Date(n.created_at).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div></article>`).join(''):'<div class="empty">No broadcasts yet.</div>'}catch(e){host.innerHTML='<div class="empty">Broadcast history unavailable.</div>'}}

