  const home=`<section class="member-hero"><div><div class="eyebrow">${esc(g.name||'Your Gym')}</div><h2>Train smarter.<br>Stay consistent.</h2><p>Welcome back, ${esc(m.name.split(' ')[0])}. Your next small win is waiting. 💙</p><div class="member-actions"><button class="btn btn-primary btn-small" id="checkInBtn">Scan & Check In</button><button class="btn btn-secondary btn-small" id="memberPlansCta">View Plans</button></div></div><div class="member-avatar-large">${photo}<div class="member-level">LEVEL ${Math.min(99,Math.max(1,Math.floor((Number(m.attendance||0)+Number(m.workoutsDone||0))/3)+1))}</div></div></section><section class="metrics"><div class="card metric"><div class="metric-label">Check-ins</div><div class="metric-value">${m.attendance||0}</div><div class="metric-sub">Total visits</div></div><div class="card metric"><div class="metric-label">Streak</div><div class="metric-value">${streak}</div><div class="metric-sub">Days consistent</div></div><div class="card metric"><div class="metric-label">Days left</div><div class="metric-value">${d<0?'0':d}</div><div class="metric-sub">${d<0?'Membership expired':'On current plan'}</div></div><div class="card metric"><div class="metric-label">BMI</div><div class="metric-value">${m.height&&m.weight?(m.weight/((m.height/100)**2)).toFixed(1):'—'}</div><div class="metric-sub">Health snapshot</div></div></section><section class="grid-2"><div class="card section-card"><div class="section-head"><h3>My Profile</h3><button id="editProfileBtn" class="mini-btn primary">Edit</button></div><div class="profile-summary">${photo}<div><h3>${esc(m.name)}</h3><p>${esc(m.phone||'')} · ${esc(m.gender||'')}</p><span class="tag success">${esc(m.status||'Active')}</span></div></div></div><div class="card section-card"><div class="section-head"><h3>Today</h3><span>${noteCount?' '+noteCount+' new notification'+(noteCount===1?'':'s'): 'You are all caught up'}</span></div><div class="connection-stack"><div class="connection-row"><span>❤️</span><div><strong>Consistency over perfection</strong><small>Show up, move a little, and let the habit compound.</small></div></div><div class="connection-row"><span>💧</span><div><strong>Hydration check</strong><small>${m.water?m.water+' L recorded today.':'Take a water break before your next set.'}</small></div></div></div></div></section>`;
