  const fitnessView=`<section class="grid-2"><div class="card page-panel"><div class="section-head"><div><h2>Health Tracker</h2><p class="page-sub">Keep your latest body metrics here.</p></div><button id="fitnessEdit" class="mini-btn">Update</button></div><div class="health-grid"><div class="health-tile"><span>Weight</span><b>${m.weight?m.weight+' kg':'Add'}</b></div><div class="health-tile"><span>Height</span><b>${m.height?m.height+' cm':'Add'}</b></div><div class="health-tile"><span>Waist</span><b>${m.waist?m.waist+' cm':'Add'}</b></div><div class="health-tile"><span>Chest</span><b>${m.chest?m.chest+' cm':'Add'}</b></div></div></div><div class="card page-panel"><div class="section-head"><div><h2>Performance</h2><p class="page-sub">Your activity snapshot.</p></div></div><div class="performance-grid"><div class="perf"><b>${Number(m.steps||0).toLocaleString('en-IN')}</b><span>Steps today</span></div><div class="perf"><b>${m.water||0} L</b><span>Water</span></div><div class="perf"><b>${m.workoutsDone||0}</b><span>Workouts</span></div><div class="perf"><b>${streak}</b><span>Day streak</span></div></div></div></section>`;
  const workoutView=`<section class="card page-panel"><div class="section-head"><div><h2>Workouts & Training</h2><p class="page-sub">Programs created by your gym.</p></div></div><div class="cards-grid">${ws.map(x=>`<article class="card member-card"><div class="member-top"><div><div class="member-name">${esc(x.name)}</div><small>${esc(x.detail||'Training')}</small></div><div class="member-avatar">${Number(x.exercises||0)}</div></div><div class="member-details"><div class="detail"><span>Schedule</span><b>${esc(x.days||'Custom')}</b></div><div class="detail"><span>Exercises</span><b>${x.exercises||0}</b></div></div><div class="member-actions"><button class="mini-btn primary" data-workout-done="${x.id}">Mark Completed</button></div></article>`).join('')||'<div class="empty">No workout templates yet.</div>'}</div></section>`;
