(async()=>{try{await loadData();startLiveSync()}catch(e){console.error(e);booting=false;app.innerHTML='<div class="auth-wrap"><div class="auth-card"><div class="auth-left"><h1 class="hero-title">GymFlow is starting…</h1><p class="hero-sub">Please refresh once the secure database connection is ready.</p><div class="error">'+esc(e.message||'Connection error')+'</div></div></div></div>'}})();
/* GymFlow AI Command Center + detail polish layer */
(function(){
  const GF_AI_KEY='gf_ai_chat_v1';
  const GF_LANG_KEY='gf_ai_lang_v1';
  const state=window.__gfAIState||(window.__gfAIState={open:false,busy:false,history:[],language:localStorage.getItem(GF_LANG_KEY)||'hinglish'});

  function aiLoad(){
    try{const raw=sessionStorage.getItem(GF_AI_KEY);if(raw){const x=JSON.parse(raw);if(Array.isArray(x))state.history=x.slice(-30)}}catch{}
  }
  function aiSave(){try{sessionStorage.setItem(GF_AI_KEY,JSON.stringify(state.history.slice(-30)))}catch{}}
  aiLoad();
  function aiText(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
  function aiLines(v){
    const safe=aiText(v);
    const parts=safe.split(/\n\s*\n/);
    return parts.map((p,i)=>{
      const ls=p.split('\n').filter(Boolean);
      if(!ls.length)return '';
      const title=i===0&&ls.length?`<div class="gf-ai-answer-title">${ls[0]}</div>`:'';
      const rest=i===0?ls.slice(1):ls;
      return `${title}${rest.map(x=>`<div class="gf-ai-row">${x.replace(/^\s*[-•]\s*/, '')}</div>`).join('')}`;
    }).join('<div class="gf-ai-gap"></div>');
  }
  function languageLabel(l){return l==='hindi'?'हिंदी':l==='hinglish'?'Hinglish':'English'}
  function setLang(l){state.language=l;localStorage.setItem(GF_LANG_KEY,l);renderAI();}
  function quickPrompts(){
    return state.language==='english'
      ? ['Show a member’s dues + attendance','What is today’s revenue?','Create a member invoice','Mark a member present']
      : state.language==='hindi'
      ? ['किसी member का बकाया और उपस्थिति बताओ','आज की आय बताओ','किसी member का invoice बनाओ','किसी member की उपस्थिति लगाओ']
      : ['Kisi member ka dues + attendance batao','Aaj ka revenue batao','Kisi member ka invoice bana do','Kisi member ko present mark karo'];
  }
  function mountAIAssistant(){
    if(active()?.role!=='owner')return;
    document.querySelectorAll('.gf-ai-fab').forEach(x=>x.remove());
    document.querySelectorAll('.gf-ai-top').forEach(x=>x.remove());
    const topbar=document.querySelector('.topbar .top-actions:last-child');
    if(topbar){
      const btn=document.createElement('button');
      btn.className='gf-ai-top icon-btn';btn.type='button';btn.title='GymFlow AI Assistant';
      btn.innerHTML=`<span class="gf-ai-spark">✦</span><span class="gf-ai-top-text">AI Assistant</span>`;
      btn.onclick=()=>openAI();topbar.insertBefore(btn,topbar.firstChild);
    }
    const fab=document.createElement('button');fab.className='gf-ai-fab';fab.type='button';fab.innerHTML='<span class="gf-ai-fab-icon">✦</span><span>Ask GymFlow AI</span>';fab.onclick=()=>openAI();document.body.appendChild(fab);
  }
  function openAI(){state.open=true;renderAI();setTimeout(()=>document.getElementById('gfAiInput')?.focus(),80)}
  function closeAI(){state.open=false;document.querySelector('.gf-ai-shell')?.remove()}
  function renderAI(){
    document.querySelector('.gf-ai-shell')?.remove();
    if(!state.open)return;
    const shell=document.createElement('div');shell.className='gf-ai-shell';
    const h=state.history.length?state.history.map((m,i)=>`<div class="gf-ai-message ${m.role==='user'?'user':'assistant'}"><div class="gf-ai-bubble">${m.role==='assistant'?aiLines(m.text):aiText(m.text)}</div>${m.action?.type?`<div class="gf-ai-action-chip">✓ ${aiText(actionLabel(m.action.type))}</div>`:''}</div>`).join(''): `<div class="gf-ai-empty"><div class="gf-ai-orb">✦</div><strong>GymFlow AI Command Center</strong><span>Ask about members, dues, attendance, payments, plans, invoices and your gym software.</span></div>`;
    const q=quickPrompts();
    shell.innerHTML=`<div class="gf-ai-backdrop" data-ai-close></div><section class="gf-ai-panel" role="dialog" aria-modal="true" aria-label="GymFlow AI Assistant">
      <header class="gf-ai-head"><div class="gf-ai-head-main"><div class="gf-ai-mini-orb">✦</div><div><div class="eyebrow">Owner Command Center</div><h3>GymFlow AI Assistant</h3><p>Live gym data · Action controls · Private to this gym</p></div></div><button class="gf-ai-close" id="gfAiClose" aria-label="Close">×</button></header>
      <div class="gf-ai-toolbar"><div class="gf-ai-status"><span class="gf-ai-live-dot"></span> Live data connected</div><div class="gf-ai-langs">${['english','hindi','hinglish'].map(x=>`<button class="gf-ai-lang ${state.language===x?'active':''}" data-lang="${x}">${languageLabel(x)}</button>`).join('')}</div></div>
      <div class="gf-ai-chat" id="gfAiChat">${h}${state.busy?`<div class="gf-ai-message assistant"><div class="gf-ai-thinking"><span class="gf-ai-progress-icon">◌</span><div><b>Working on it</b><small>Checking your gym data and preparing the answer</small></div><span class="gf-ai-dots"><i></i><i></i><i></i></span></div></div>`:''}</div>
      <div class="gf-ai-quick">${q.map(x=>`<button class="gf-ai-chip" data-prompt="${aiText(x)}">${aiText(x)}</button>`).join('')}</div>
      <form class="gf-ai-compose" id="gfAiForm"><textarea id="gfAiInput" rows="1" maxlength="900" placeholder="Ask your gym or GymFlow question..."></textarea><button id="gfAiSend" class="gf-ai-send" type="submit" ${state.busy?'disabled':''}>↑</button></form>
      <div class="gf-ai-foot">Focused on GymFlow & gym-management tasks. Sensitive destructive actions stay behind the normal controls.</div>
    </section>`;
    document.body.appendChild(shell);
    shell.querySelector('[data-ai-close]').onclick=closeAI;shell.querySelector('#gfAiClose').onclick=closeAI;
    shell.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));
    shell.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{const input=document.getElementById('gfAiInput');if(input){input.value=b.dataset.prompt;input.focus()}});
    shell.querySelector('#gfAiForm').onsubmit=async e=>{e.preventDefault();const input=document.getElementById('gfAiInput');const q=input?.value.trim();if(q&&!state.busy){input.value='';await sendAI(q)}};
    const chat=document.getElementById('gfAiChat');if(chat)chat.scrollTop=chat.scrollHeight;
  }
  function actionLabel(t){return ({create_invoice:'Invoice created',mark_attendance:'Attendance marked',record_payment:'Payment recorded',update_member_status:'Member status updated',renew_member:'Membership renewed'})[t]||'Action completed'}
  function push(role,text,action){state.history.push({role,text,action:action||null,at:Date.now()});aiSave()}
  function syncAction(action){
    if(!action)return;
    const type=action.type;
    if(type==='create_invoice'&&action.record){store.invoices=store.invoices||[];store.invoices.unshift(action.record)}
    if(type==='record_payment'&&action.record){store.payments=store.payments||[];store.payments.unshift(action.record);if(action.member){store.members=(store.members||[]).map(x=>x.id===action.member.id?action.member:x)}}
    if(type==='mark_attendance'&&action.record){store.attendance=store.attendance||[];store.attendance.unshift(action.record);if(action.member){store.members=(store.members||[]).map(x=>x.id===action.member.id?action.member:x)}}
    if(type==='update_member_status'&&action.member){store.members=(store.members||[]).map(x=>x.id===action.member.id?action.member:x)}
    if(type==='renew_member'&&action.member){store.members=(store.members||[]).map(x=>x.id===action.member.id?action.member:x)}
  }
  async function sendAI(question){
    state.busy=true;push('user',question);renderAI();
    try{
      const data=await callFunction('gymflow-ai',{question,language:state.language});
      if(!data?.ok)throw new Error(data?.error||'Assistant could not complete the request.');
      syncAction(data.action);
      if(data.action&&['create_invoice','record_payment','mark_attendance','update_member_status','renew_member'].includes(data.action.type))renderSection();
      if(data.navigate&&data.navigate!==activeSection){
        activeSection=data.navigate;
        renderSection();
      }
      push('assistant',data.answer||'Done.',data.action||null);
    }catch(e){
      push('assistant',state.language==='hindi'?'Assistant abhi request complete nahi kar paaya. Please same question dobara try karein.':state.language==='hinglish'?'Assistant abhi request complete nahi kar paaya. Same question ek baar phir try karo.':'I could not complete that request right now. Please try the same question again.');
    }finally{state.busy=false;renderAI();}
  }
  function setupOwnerAI(){
    if(window.__gfAiSetupDone)return;window.__gfAiSetupDone=true;
    const base=renderOwner;
    renderOwner=function(){base();mountAIAssistant();};
  }

  function chartDays(){const out=[];const now=new Date();for(let i=6;i>=0;i--){const d=new Date(now);d.setDate(d.getDate()-i);const key=d.toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});out.push({key,label:d.toLocaleDateString('en-IN',{weekday:'short',day:'2-digit'})})}return out}
  function overviewSeries(){const {m,pay}=ownerData();const att=attendance().filter(x=>x.gymId===active().gymId);const days=chartDays();return {revenue:days.map(d=>pay.filter(x=>x.date===d.key).reduce((s,x)=>s+Number(x.amount||0),0)),attendance:days.map(d=>att.filter(x=>x.date===d.key).length),days,m};}
  function barChart(title,values,days,unit){const max=Math.max(1,...values);return `<div class="gf-chart card"><div class="gf-chart-head"><div><strong>${title}</strong><span>Last 7 days</span></div><span class="gf-chart-live">LIVE</span></div><div class="gf-bars">${values.map((v,i)=>`<div class="gf-bar-wrap"><div class="gf-bar-value">${unit}${Number(v).toLocaleString('en-IN')}</div><div class="gf-bar-track"><div class="gf-bar" style="--h:${Math.max(8,(v/max)*100)}%;--d:${i*65}ms"></div></div><div class="gf-bar-label">${days[i].label}</div></div>`).join('')}</div></div>`}
  function donutCard(m){const blocked=m.filter(x=>x.status==='Blocked').length;const expired=m.filter(x=>x.status!=='Blocked'&&daysLeft(x.expiry)<0).length;const due=m.filter(x=>x.status!=='Blocked'&&daysLeft(x.expiry)>=0&&(x.status==='Due'||Number(x.dueAmount||0)>0)).length;const activeCount=Math.max(0,m.length-blocked-expired-due);const total=Math.max(1,m.length);const activePct=Math.round(activeCount/total*100);return `<div class="gf-chart card gf-donut-card"><div class="gf-chart-head"><div><strong>Member Status Mix</strong><span>Live membership health</span></div><span class="gf-chart-live">${m.length} MEMBERS</span></div><div class="gf-donut-layout"><div class="gf-donut" style="--gf-p:${activePct}"><div class="gf-donut-inner"><b>${activePct}%</b><span>Active</span></div></div><div class="gf-legend"><div><i class="dot active"></i><span>Active</span><b>${activeCount}</b></div><div><i class="dot due"></i><span>Due</span><b>${due}</b></div><div><i class="dot expired"></i><span>Expired</span><b>${expired}</b></div><div><i class="dot blocked"></i><span>Blocked</span><b>${blocked}</b></div></div></div></div>`}
  renderOverview=function(){
    const {m,pay}=ownerData();const activeCount=m.filter(x=>x.status!=='Blocked'&&daysLeft(x.expiry)>=0).length;const due=m.filter(x=>x.status==='Due'||daysLeft(x.expiry)<=3).length;const exp=m.filter(x=>daysLeft(x.expiry)>=0&&daysLeft(x.expiry)<=7).length;const revenue=pay.reduce((s,x)=>s+Number(x.amount||0),0);const requests=orders().filter(x=>x.status==='Pending');const recent=m.slice(0,5);const todayAtt=attendance().filter(x=>x.gymId===active().gymId&&x.date===today()).length;const ser=overviewSeries();
    const g=ownerData().g;
    document.getElementById('pageContent').innerHTML=`<section class="hero-panel gf-enter"><div><div class="eyebrow">Owner Command Center</div><div class="gf-hero-label">Smart gym operations</div><h2>Your gym, your numbers, your next action.</h2><p>Members, memberships, attendance, payments and invoices in one calm workspace — now with an AI command layer.</p><div class="hero-stats"><div class="kpi-pill"><b>${activeCount}</b> active members</div><div class="kpi-pill"><b>${due}</b> urgent dues</div><div class="kpi-pill"><b>${exp}</b> expiring soon</div><div class="kpi-pill"><b>${requests.length}</b> UPI requests</div></div><div class="quick-actions"><button id="qaAdd" class="btn btn-primary btn-small">+ Add Member</button><button id="qaPlans" class="btn btn-secondary btn-small">Manage Plans</button><button id="qaPay" class="btn btn-secondary btn-small">Payment Center</button><button id="qaAI" class="btn btn-secondary btn-small">✦ Ask AI</button></div></div><div class="hero-graphic"><div class="hero-ring"></div><div class="hero-glyph">GF</div><div class="gf-hero-chip"><span class="gf-ai-live-dot"></span> AI command ready</div></div></section><section class="metrics gf-stagger"><div class="card metric"><div class="metric-label">Total Members</div><div class="metric-value">${m.length}</div><div class="metric-sub">All member records</div><div class="metric-accent"><span style="width:${Math.min(100,m.length*10)}%"></span></div></div><div class="card metric"><div class="metric-label">Collected Payments</div><div class="metric-value">₹${revenue.toLocaleString('en-IN')}</div><div class="metric-sub">Recorded payment total</div><div class="metric-accent"><span style="width:${Math.min(100,24+pay.length*4)}%"></span></div></div><div class="card metric"><div class="metric-label">Pending Dues</div><div class="metric-value">${due}</div><div class="metric-sub">Members need follow-up</div><div class="metric-accent"><span style="width:${Math.max(10,Math.min(100,due*25))}%"></span></div></div><div class="card metric"><div class="metric-label">Today's Check-ins</div><div class="metric-value">${todayAtt}</div><div class="metric-sub">Live attendance records</div><div class="metric-accent"><span style="width:${Math.min(100,todayAtt*12)}%"></span></div></div></section><section class="gf-dashboard-grid gf-stagger">${barChart('Revenue Trend',ser.revenue,ser.days,'₹')}${barChart('Attendance Trend',ser.attendance,ser.days,'')}</section><section class="gf-dashboard-grid gf-stagger">${donutCard(m)}<div class="card section-card gf-command-card"><div class="section-head"><div><h3>AI Quick Control</h3><span>Natural language → action</span></div><span class="gf-command-badge">Connected</span></div><div class="gf-command-list"><button class="gf-command-row" data-ai-cmd="Kisi member ka dues aur attendance batao"><div class="gf-command-icon">₹</div><div><strong>Check member dues + attendance</strong><small>Ask the Assistant for one member snapshot</small></div><span>→</span></button><button class="gf-command-row" data-ai-cmd="Aaj ka revenue batao"><div class="gf-command-icon">↗</div><div><strong>See today's revenue</strong><small>Get the latest recorded payment total</small></div><span>→</span></button><button class="gf-command-row" data-ai-cmd="Kisi member ka invoice bana do"><div class="gf-command-icon">▣</div><div><strong>Create a member invoice</strong><small>Use the member's plan price when available</small></div><span>→</span></button><button class="gf-command-row" data-ai-cmd="Kisi member ko present mark karo"><div class="gf-command-icon">✓</div><div><strong>Mark attendance</strong><small>AI checks membership status and duplicates</small></div><span>→</span></button></div></div></section><section class="grid-2 gf-stagger"><div class="card section-card"><div class="section-head"><h3>Member Pulse</h3><span>Live records</span></div><div class="table"><div class="row head"><div>Member</div><div>Plan</div><div>Expiry</div><div>Status</div></div>${recent.length?recent.map(mm=>`<div class="row"><div class="member-mini"><div class="member-mini-avatar">${initials(mm.name)}</div><div><strong>${esc(mm.name)}</strong><small>${esc(mm.phone||'')} · code ${mm.code}</small></div></div><div>${esc(mm.plan||'—')}</div><div>${fmtDate(mm.expiry)}</div><div>${statusTag(mm)}</div></div>`).join(''):'<div class="empty">No members yet. Add your first member.</div>'}</div></div><div class="card section-card"><div class="section-head"><h3>Payment & Setup</h3><span>Owner control</span></div><div class="list"><button class="list-item mini-btn" id="ovUpi"><div><strong>UPI Checkout</strong><small>${validUpiId(g.upi)?esc(g.upi)+' · exact plan amount links ready':'Add your UPI ID to accept plan payments'}</small></div><div>→</div></button><button class="list-item mini-btn" id="ovPayReq"><div><strong>Payment Requests</strong><small>${requests.length} online request${requests.length===1?'':'s'} awaiting confirmation</small></div><div>→</div></button><button class="list-item mini-btn" id="ovInvoice"><div><strong>Invoices</strong><small>Create, print or save branded PDF receipts</small></div><div>→</div></button></div></div></section>`;
    qaAdd.onclick=openAddMember;qaPlans.onclick=()=>{activeSection='plans';render()};qaPay.onclick=()=>{activeSection='payments';render()};qaAI.onclick=openAI;ovUpi.onclick=()=>{activeSection='payments';render()};ovPayReq.onclick=()=>{activeSection='payments';render()};ovInvoice.onclick=()=>openInvoice();document.querySelectorAll('[data-ai-cmd]').forEach(b=>b.onclick=()=>{openAI();setTimeout(()=>{const i=document.getElementById('gfAiInput');if(i){i.value=b.dataset.aiCmd;i.focus()}},60)});
  };

  window.GymFlowAI={open:openAI,mount:mountAIAssistant};
  setupOwnerAI();
  if(active()?.role==='owner')mountAIAssistant();
})();
